mapper.insert:
INSERT INTO TB_UNLIKE (
    post_idx,
    member_idx
) VALUES (
    #{postIdx},
    #{memberIdx}
)

INSERT INTO TB_UNLIKE (
    comment_idx,
    member_idx
) VALUES (
    #{commentIdx},
    #{memberIdx}
)

mapper.select:
SELECT COUNT(*)
FROM TB_UNLIKE
WHERE post_idx = #{postIdx}

SELECT COUNT(*)
FROM TB_UNLIKE
