mapper.delete:
DELETE FROM TB_UNLIKE
WHERE post_idx = #{postIdx}
AND member_idx = #{memberIdx}

DELETE FROM TB_UNLIKE
WHERE comment_idx = #{commentIdx}
AND member_idx = #{memberIdx}
